<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Resources\ProductResource; use App\Repositories\Contracts\ProductRepository; use Illuminate\Http\Request;
class ProductController extends Controller { public function __construct(private ProductRepository $products){} public function index(Request $request){$data=$request->validate(['q'=>'nullable|string|max:120','category'=>'nullable|string','vendor'=>'nullable|string','location'=>'nullable|string','min_price'=>'nullable|numeric|min:0','max_price'=>'nullable|numeric|min:0','per_page'=>'nullable|integer|min:1|max:50']);return ProductResource::collection($this->products->search($data));} public function show(string $slug){return new ProductResource($this->products->findPublic($slug));} }
